mapper.update:
IF EXISTS (SELECT 1 FROM sys_permission WHERE permission_code = #{permissionCode})
    UPDATE sys_permission
    SET permission_name = #{permissionName}
    WHERE permission_code = #{permissionCode};
ELSE
    INSERT INTO sys_permission (permission_code, permission_name)
    VALUES (#{permissionCode}, #{permissionName});

mapper.select:
INSERT INTO sys_role (
    role_code, role_name, is_enabled, is_system_managed, created_by, updated_by
) VALUES (
    #{roleCode}, #{roleName}, 1, 1, #{actor}, #{actor}
);
SELECT CONVERT(BIGINT, SCOPE_IDENTITY());

INSERT INTO sys_user (
    login_name, display_name, password_hash, primary_organization_id,
    is_enabled, must_change_password, created_by, updated_by
) VALUES (
    #{command.loginName}, #{command.displayName}, #{passwordHash}, #{organizationId},
    1, 1, #{actor}, #{actor}
);
SELECT CONVERT(BIGINT, SCOPE_IDENTITY());
